// Tenant routing resolution
function getRegionForTenant(tenantId) {
  const tenantConfig = dynamodb.get(tenantId);
  return tenantConfig.region || getDefaultRegion();
}

function routeEvent(event) {
  const region = getRegionForTenant(event.tenantId);
  const stream = getKinesisStream(region);
  return stream.putRecord({
    partitionKey: `${event.tenantId}_${event.timestamp}`,
    data: JSON.stringify(event),
    dedupeId: generateDedupeId(event)
  });
}
```

